mapper.select:
SELECT st.*,
       sdi2.sys_dict_item_name         sysDictItem2Name,
       sdi1.sys_dict_item_name         sysDictItem1Name,
       sdi3.sys_dict_item_name         sysDictItem3Name,
       sdi2.sys_dict_item_code         sysDictItem2Code,
       sdi1.sys_dict_item_code         sysDictItem1Code,
       sdi3.sys_dict_item_code         sysDictItem3Code
FROM sys_template st
         LEFT JOIN sys_dict_item sdi2 ON sdi2.sys_dict_item_id = st.sys_dict_item_id2 and sdi2.sys_dict_id = 2
         LEFT JOIN sys_dict_item sdi1 ON sdi1.sys_dict_item_id = st.sys_dict_item_id1 and sdi1.sys_dict_id = 1
         LEFT JOIN sys_dict_item sdi3 ON sdi3.sys_dict_item_id = st.sys_dict_item_id3 and sdi3.sys_dict_id IN (
            SELECT sd.sys_dict_id FROM sys_dict sd WHERE sd.sys_dict_pid = 2
         )


        AND st.sys_dict_item_id1 = #{query.sysDictItemId1}


        AND st.sys_dict_item_id2 = #{query.sysDictItemId2}


        AND st.sys_dict_item_id3 = #{query.sysDictItemId3}



        AND sdi1.sys_dict_item_name LIKE CONCAT('%', #{query.sysDictItem1Name}, '%')



        AND sdi2.sys_dict_item_name LIKE CONCAT('%', #{query.sysDictItem2Name}, '%')



        AND sdi3.sys_dict_item_name LIKE CONCAT('%', #{query.sysDictItem3Name}, '%')



        AND sdi1.sys_dict_item_code  = #{query.sysDictItem1Code}



        AND sdi2.sys_dict_item_code  = #{query.sysDictItem2Code}



        AND sdi3.sys_dict_item_code  = #{query.sysDictItem3Code}



        AND st.sys_template_name LIKE CONCAT('%', #{query.sysTemplateName}, '%')



        AND st.sys_template_code LIKE CONCAT('%', #{query.sysTemplateCode}, '%')



        AND st.sys_template_status = #{query.sysTemplateStatus}



        AND st.sys_template_type = #{query.sysTemplateType}



        AND st.sys_template_approve = #{query.sysTemplateApprove}



        AND st.sys_template_approve_reject LIKE CONCAT('%', #{query.sysTemplateApproveReject}, '%')



        AND st.sys_template_approve_create_by = #{query.sysTemplateApproveCreateBy}



        AND st.sys_template_delete = 0



        AND st.sys_template_delete = #{query.sysTemplateDelete}


ORDER BY st.sys_template_sort,
st.create_time DESC
